scriptdefs
= LilycoveCity_LilycoveMuseum_2F_EventScript_ShowExhibitHall
lockall
applymovement LOCALID_MUSEUM_2F_CURATOR Common_Movement_FacePlayer
applymovement LOCALID_PLAYER LilycoveCity_LilycoveMuseum_2F_Movement_PlayerWalkInPlaceLeft
waitmovement 0
msgbox	Das ist unser besonderer Ausstellungssaal.
applymovement LOCALID_MUSEUM_2F_CURATOR LilycoveCity_LilycoveMuseum_2F_Movement_FaceExhibitHall
waitmovement 0
applymovement LOCALID_PLAYER LilycoveCity_LilycoveMuseum_2F_Movement_FaceExhibitHall
waitmovement 0
msgbox	Wie du deutlich sehen kannst, hängt hier nicht ein einziges Gemälde.Hier möchte ich keine Werke sogenannter klassischer Kunst ausstellen.Solche klassischen Werke kannst du in unserem Erdgeschoss sehen.Ich möchte Werke ausstellen, die sich weit von den Klassikern unterscheiden.Kunst ist schließlich nicht auf alte, berühmte Werke beschränkt!Diesen Ausstellungssaal möchte ich füllen mit…Modernen und lebendigen Kunstwerken von POKéMON, die bereit scheinen, voller Leben hervorzuspringen!
applymovement LOCALID_MUSEUM_2F_CURATOR Common_Movement_FacePlayer
waitmovement 0
applymovement LOCALID_PLAYER LilycoveCity_LilycoveMuseum_2F_Movement_PlayerWalkInPlaceLeft
waitmovement 0
msgbox	Verzeih mir. Ich wollte das Gespräch nicht ganz für mich beanspruchen.Nun, da du jung, aber offensichtlich weit gereist bist…Wirst du sicher lebendigen POKéMON begegnen und Kunstwerken, die sie darstellen.Solltest du auf so ein Gemälde stoßen, dürften wir dich bitten, die Erlaubnis des Künstlers einzuholen, es hier auszustellen?
copyvar VAR_LILYCOVE_MUSEUM_2F_STATE 1 warn=FALSE
releaseall
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_RichBoy
msgbox	Wow, ist das wahr? Diese Gemälde zeigen dein POKéMON.Ist das nicht die ultimative Freude für einen TRAINER?
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_ExpertM
msgbox	Nun… Hier zeigt man also die aktuellen POKéMON-Gemälde.Ich sehe schon, diese neuen Gemälde sind wirklich recht amüsant.
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_Girl
msgbox	Ich war eine Weile weg, deshalb haben mich die neuen Gemälde hier oben überrascht.Ich wünschte, jemand würde mein POKéMON genauso hübsch malen.
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_Curator
lockall
goto_if_set FLAG_RECEIVED_GLASS_ORNAMENT LilycoveCity_LilycoveMuseum_2F_EventScript_ReceivedGlassOrnament
specialvar VAR_0x8004 CountPlayerMuseumPaintings
switch VAR_0x8004
case 1 LilycoveCity_LilycoveMuseum_2F_EventScript_AddedPainting
case 2 LilycoveCity_LilycoveMuseum_2F_EventScript_AddedPainting
case 3 LilycoveCity_LilycoveMuseum_2F_EventScript_AddedPainting
case 4 LilycoveCity_LilycoveMuseum_2F_EventScript_AddedPainting
case 5 LilycoveCity_LilycoveMuseum_2F_EventScript_ThankPlayer
msgbox	Ich möchte diesen Ausstellungssaal mit modernen und lebendigen Gemälden von POKéMON füllen.
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_ThankPlayer
applymovement LOCALID_MUSEUM_2F_CURATOR Common_Movement_FacePlayer
waitmovement 0
msgbox	Ah! Du bist es! PLAYER!
applymovement LOCALID_MUSEUM_2F_CURATOR LilycoveCity_LilycoveMuseum_2F_Movement_FaceExhibitHall
msgbox	Ist das nicht wunderbar? Diese Sammlung von Gemälden!Jedes Einzelne makellos! Keines besser als das andere!Diese Gemälde haben mehr Besucher in unser KUNSTMUSEUM gelockt.Von Herzen danke ich dir, PLAYER. Das ist mein wahr gewordener Traum!
goto LilycoveCity_LilycoveMuseum_2F_EventScript_GiveGlassOrnament
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_GiveGlassOrnament
applymovement LOCALID_MUSEUM_2F_CURATOR Common_Movement_FacePlayer
msgbox	Das ist nur ein kleines Zeichen meiner Dankbarkeit.
givedecoration DECOR_GLASS_ORNAMENT
goto_if_eq VAR_RESULT FALSE LilycoveCity_LilycoveMuseum_2F_EventScript_NoRoomForGlassOrnament
setflag FLAG_RECEIVED_GLASS_ORNAMENT
closemessage
releaseall
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_NoRoomForGlassOrnament
call Common_EventScript_NoRoomForDecor
msgbox	Ich bewahre das für dich auf, bis wir uns wiedersehen.
closemessage
releaseall
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_AddedPainting
msgbox	Dank dir haben wir unserer Sammlung ein neues Gemälde hinzugefügt!Ich habe gehört, es zeigt dein POKéMON. Wirklich großartig!Vielen, vielen Dank!
end
= LilycoveCity_LilycoveMuseum_2F_EventScript_ReceivedGlassOrnament
msgbox	Ah, wie schön, dich zu sehen, PLAYER!Es ist mir eine Ehre, dass du uns auf deinen geschäftigen Reisen besuchst.Bitte entspann dich und genieß deinen Besuch bei uns.
releaseall
end
